import pandas as pd
import requests
from datetime import datetime, timezone

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

BASE = 'https://www.metaculus.com/api2/questions/'
try:
    TOKEN = (CREDENTIALS.get('METACULUS_API_TOKEN', '') or '').strip()
except NameError:
    # No CREDENTIALS dict injected (older test path or no-creds engine);
    # behave as the unauthenticated case.
    TOKEN = ''

EXPECTED_COLUMNS = [
    'question_id', 'title', 'question_type',
    'community_prediction', 'prediction_count',
    'comment_count', 'forecaster_count',
    'created_time', 'publish_time', 'resolve_time',
    'days_to_resolve', 'category', 'page_url', '_epoch',
]

def sentinel_row(title, category):
    return {
        'question_id': 0,
        'title': title[:400],
        'question_type': 'INFO',
        'community_prediction': None,
        'prediction_count': 0,
        'comment_count': 0,
        'forecaster_count': 0,
        'created_time': '',
        'publish_time': '',
        'resolve_time': '',
        'days_to_resolve': 0,
        'category': category,
        'page_url': 'https://www.metaculus.com/',
        '_epoch': now_epoch,
    }

headers = {'User-Agent': 'speakesquery (forecasting-brief) ingestion'}
if TOKEN:
    headers['Authorization'] = 'Token ' + TOKEN

rows = []
auth_failure = False
fetch_error = ''
offset = 0
page_size = 50
max_pages = 4
for page_idx in range(max_pages):
    try:
        resp = requests.get(
            BASE,
            params={
                'limit': page_size,
                'offset': offset,
                'status': 'open',
                'order_by': '-prediction_count',
            },
            headers=headers,
            timeout=30,
        )
    except Exception as exc:
        fetch_error = (str(exc) or '')[:200]
        break
    if resp.status_code in (401, 403):
        auth_failure = True
        fetch_error = 'HTTP ' + str(resp.status_code) + ': ' + (resp.text or '')[:200]
        break
    if resp.status_code != 200:
        fetch_error = 'HTTP ' + str(resp.status_code) + ': ' + (resp.text or '')[:200]
        break
    try:
        payload = resp.json() or {}
    except Exception as exc:
        fetch_error = 'JSON parse: ' + (str(exc) or '')[:200]
        break
    results = payload.get('results', []) or []
    if not results:
        break
    for ri in range(len(results)):
        q = results[ri]
        if not isinstance(q, dict):
            continue
        # Post-level fields (top-level of /api2/questions/ result)
        qid = q.get('id', 0)
        title = q.get('title', '') or ''
        slug = q.get('slug', '') or ''

        # Question-specific data was hoisted to a nested `question` object
        # in the 2026-Q1 V2 schema migration. Pre-fix the script read
        # everything from top-level keys; many of those keys still exist
        # but several moved or were renamed. Read the new path first;
        # fall back to legacy paths for backward compatibility with any
        # mocked test fixtures.
        question_data = q.get('question', {}) or {}

        # question type: q.question.type (V2) -> q.possibilities.type (legacy)
        # -> q.type (older legacy) -> 'binary' (default)
        qtype = ''
        if isinstance(question_data, dict):
            qtype = question_data.get('type', '') or ''
        if not qtype:
            possibilities = q.get('possibilities', {}) or {}
            if isinstance(possibilities, dict):
                qtype = possibilities.get('type', '') or ''
        if not qtype:
            qtype = q.get('type', '') or 'binary'

        # community prediction:
        #   V2: q.question.aggregations.recency_weighted.latest.centers[0]
        #       (binary -> single value; multi-choice -> array)
        #   legacy: q.community_prediction.full.q2 OR q.aggregations.recency_weighted.center
        community_pred = None
        if isinstance(question_data, dict):
            aggs = question_data.get('aggregations', {}) or {}
            if isinstance(aggs, dict):
                rec = aggs.get('recency_weighted', {}) or {}
                if isinstance(rec, dict):
                    latest = rec.get('latest') or {}
                    if isinstance(latest, dict):
                        # Try centers[0] (most common shape), then center, then means[0]
                        centers = latest.get('centers')
                        if isinstance(centers, list) and centers:
                            try:
                                community_pred = round(float(centers[0]), 4)
                            except Exception:
                                community_pred = None
                        if community_pred is None:
                            cv = latest.get('center')
                            if cv is not None:
                                try:
                                    community_pred = round(float(cv), 4)
                                except Exception:
                                    community_pred = None
                        if community_pred is None:
                            means = latest.get('means')
                            if isinstance(means, list) and means:
                                try:
                                    community_pred = round(float(means[0]), 4)
                                except Exception:
                                    community_pred = None
        # legacy fallback paths
        if community_pred is None:
            cp_obj = q.get('community_prediction', {}) or {}
            if isinstance(cp_obj, dict):
                full_obj = cp_obj.get('full', {}) or {}
                if isinstance(full_obj, dict):
                    q2 = full_obj.get('q2')
                    if q2 is not None:
                        try:
                            community_pred = round(float(q2), 4)
                        except Exception:
                            community_pred = None
        if community_pred is None:
            ap = q.get('aggregations', {}) or {}
            if isinstance(ap, dict):
                rec_legacy = ap.get('recency_weighted', {}) or {}
                if isinstance(rec_legacy, dict):
                    cv = rec_legacy.get('center')
                    if cv is not None:
                        try:
                            community_pred = round(float(cv), 4)
                        except Exception:
                            community_pred = None

        # forecast count: V2 renamed prediction_count -> forecasts_count
        prediction_count = q.get('forecasts_count', 0) or q.get('prediction_count', 0) or 0
        forecaster_count = q.get('nr_forecasters', 0) or q.get('number_of_forecasters', 0) or 0
        comment_count = q.get('comment_count', 0) or 0

        # timestamps: V2 renames created_time->created_at, publish_time->published_at,
        # resolve_time->scheduled_resolve_time (or actual_resolve_time when resolved)
        created_time = q.get('created_at', '') or q.get('created_time', '') or ''
        publish_time = q.get('published_at', '') or q.get('publish_time', '') or ''
        resolve_time = (
            q.get('actual_resolve_time', '')
            or q.get('scheduled_resolve_time', '')
            or q.get('resolve_time', '')
            or ''
        )
        # Fallback to question-level resolve time
        if not resolve_time and isinstance(question_data, dict):
            resolve_time = (
                question_data.get('actual_resolve_time', '')
                or question_data.get('scheduled_resolve_time', '')
                or ''
            )

        days_to_resolve = 0
        if resolve_time:
            try:
                rt = datetime.fromisoformat(resolve_time.replace('Z', '+00:00'))
                days_to_resolve = round((rt - now).total_seconds() / 86400.0, 1)
            except Exception:
                days_to_resolve = 0

        # categories: V2 moved to q.projects.category[] (each item has `name`)
        # Legacy: q.categories[] (each item has `long_name`/`name`/`short_name`)
        cat_names = []
        projects = q.get('projects', {}) or {}
        if isinstance(projects, dict):
            cat_list = projects.get('category', []) or []
            if isinstance(cat_list, list):
                for ci in range(len(cat_list)):
                    c = cat_list[ci]
                    if isinstance(c, dict):
                        cn = c.get('name', '') or ''
                        if cn:
                            cat_names.append(cn)
        # legacy fallback
        if not cat_names:
            categories = q.get('categories', []) or []
            if isinstance(categories, list):
                for ci in range(len(categories)):
                    c = categories[ci]
                    if isinstance(c, dict):
                        cn = c.get('long_name', '') or c.get('name', '') or c.get('short_name', '')
                        if cn:
                            cat_names.append(cn)
                    elif isinstance(c, str):
                        cat_names.append(c)
        cat_str = '; '.join(cat_names[:3])

        # page_url: V2 doesn't include it; build from id+slug
        page_url = q.get('page_url', '') or ''
        if page_url and not page_url.startswith('http'):
            page_url = 'https://www.metaculus.com' + page_url
        if not page_url:
            if slug:
                page_url = 'https://www.metaculus.com/questions/' + str(qid) + '/' + slug + '/'
            else:
                page_url = 'https://www.metaculus.com/questions/' + str(qid) + '/'

        rows.append({
            'question_id': int(qid) if qid else 0,
            'title': title[:400] if len(title) > 400 else title,
            'question_type': qtype,
            'community_prediction': community_pred,
            'prediction_count': int(prediction_count) if prediction_count else 0,
            'comment_count': int(comment_count) if comment_count else 0,
            'forecaster_count': int(forecaster_count) if forecaster_count else 0,
            'created_time': created_time,
            'publish_time': publish_time,
            'resolve_time': resolve_time,
            'days_to_resolve': days_to_resolve,
            'category': cat_str,
            'page_url': page_url,
            '_epoch': now_epoch,
        })
    if len(results) < page_size:
        break
    offset = offset + page_size

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
    df = df.sort_values('prediction_count', ascending=False).reset_index(drop=True)
elif auth_failure and not TOKEN:
    df = pd.DataFrame([sentinel_row(
        'Metaculus API requires authentication: register at metaculus.com/account, copy your API token, and add METACULUS_API_TOKEN as a credential in Settings > Global Credentials. The script auto-detects the token and sends it as Authorization: Token <value>.',
        'AUTH_REQUIRED',
    )], columns=EXPECTED_COLUMNS)
elif auth_failure and TOKEN:
    df = pd.DataFrame([sentinel_row(
        'METACULUS_API_TOKEN is set but the API rejected it: ' + fetch_error,
        'AUTH_INVALID',
    )], columns=EXPECTED_COLUMNS)
elif fetch_error:
    df = pd.DataFrame([sentinel_row(
        'Metaculus API call failed: ' + fetch_error,
        'API_ERROR',
    )], columns=EXPECTED_COLUMNS)
else:
    df = pd.DataFrame([sentinel_row(
        'Metaculus API returned no questions matching status=open. Check filter or try again later.',
        'NO_SIGNAL',
    )], columns=EXPECTED_COLUMNS)

GENERATE_RESULTS(df)
